scwin.vScrenProcTpCd = undefined;


///////// 2. 초기화 영역 /////////

/**
 * @method
 * @name scwin.init_pageBody
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.init_pageBody = async function () {
    try {
        /* sdd-asis-lifecycle:begin onpageload — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
        const parentWin = $c.frame.Provider("../");
        scwin.vBzProcsNo = parentWin.clickBzProcsNo;
        scwin.vListProcsStatCd = parentWin.clickListProcsStatCd;
        scwin.fn_common_info();
        await scwin.syncPub();
        scwin.initForm(scwin.vListProcsStatCd);
        await scwin.syncFnc();
        setTimeout(function(){ scwin.setPubOfrGrid(scwin.grid_PubOfrList, scwin.dts_PubOfrList) }, 500);
        setTimeout(function(){ scwin.setPriOfrGrid(scwin.grid_PriOfrList, scwin.dts_PriOfrList) }, 500);
        setTimeout(function(){ scwin.setAssgnGrid(scwin.grid_AssgnList, scwin.dts_AssgnList) }, 500);
        setTimeout(function(){ scwin.setPriOfrAssgnGrid(scwin.grid_PriOfrAssgnList, scwin.dts_PriOfrAssgnList) }, 500);
        setTimeout(function(){ scwin.setBIGrid(scwin.grd_BIList, scwin.dts_BIList) }, 500);
        setTimeout(function(){ scwin.setBSGrid(scwin.grd_BSList, scwin.dts_BSList) }, 500);
        setTimeout(function(){ scwin.setPLGrid(scwin.grd_PLList, scwin.dts_PLList) }, 500);
        setTimeout(function(){ scwin.setCFGrid(scwin.grd_CFList, scwin.dts_CFList) }, 500);
        /* sdd-asis-lifecycle:end */

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldstf07311.onpageload' }); }
};

// 화면 전환 파라미터 수신 — 엔진 표준(§106). 진입 파라미터 전체를 컨텍스트 dataMap 에 담는다. onpageload 합성 단계.
/**
 * @method
 * @name scwin.init_recvParam
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.init_recvParam = function () { console.warn("[sdd] 전환 파라미터 수신 대상 없음: dma_pageContext — 읽는 자리 0"); };

scwin.dts_common_info = typeof __krxRowShim === 'function' ? __krxRowShim($c.util.getComponent('dtsCommonInfo')) : $c.util.getComponent('dtsCommonInfo');

scwin.dts_PubOfr = typeof __krxRowShim === 'function' ? __krxRowShim($c.util.getComponent('dts_PubOfr')) : $c.util.getComponent('dts_PubOfr');

scwin.dts_PubOfrList = typeof __krxRowShim === 'function' ? __krxRowShim($c.util.getComponent('dts_PubOfrList')) : $c.util.getComponent('dts_PubOfrList');

scwin.dts_AssgnList = typeof __krxRowShim === 'function' ? __krxRowShim($c.util.getComponent('dts_AssgnList')) : $c.util.getComponent('dts_AssgnList');

scwin.dts_Fnc = typeof __krxRowShim === 'function' ? __krxRowShim($c.util.getComponent('dts_Fnc')) : $c.util.getComponent('dts_Fnc');

scwin.dts_BIList = typeof __krxRowShim === 'function' ? __krxRowShim($c.util.getComponent('dts_BIList')) : $c.util.getComponent('dts_BIList');

scwin.dts_BSList = typeof __krxRowShim === 'function' ? __krxRowShim($c.util.getComponent('dts_BSList')) : $c.util.getComponent('dts_BSList');

scwin.dts_PLList = typeof __krxRowShim === 'function' ? __krxRowShim($c.util.getComponent('dts_PLList')) : $c.util.getComponent('dts_PLList');

scwin.dts_CFList = typeof __krxRowShim === 'function' ? __krxRowShim($c.util.getComponent('dts_CFList')) : $c.util.getComponent('dts_CFList');

