scwin.setPubOfrDataSet = function (dtsObj_1, idx, val_1, val_2, val_3, val_4) {
    /* sdd-asis-lifecycle:begin fn_setPubOfrDataSet — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    (dtsObj_1.insertRow(), dtsObj_1.setRowPosition(dtsObj_1.getRowCount()-1));
    dtsObj_1.setCellData(idx, "TYPE", val_1);
    dtsObj_1.setCellData(idx, "SHARES", val_2);
    dtsObj_1.setCellData(idx, "LWLMT_PUBOFR_SCHDL_AMT", val_3);
    dtsObj_1.setCellData(idx, "UPLMT_PUBOFR_SCHDL_AMT", val_4);
    /* sdd-asis-lifecycle:end */
};


