/**
 * @method
 * @name scwin.syncPub
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.syncPub = async function () {
    /* sdd-asis-lifecycle:begin fn_sync_pub — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    let url = "/konex/PubFncKonex.do?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + $c.fil.SCREN_PROCS_TP_CD_01 + "&method=readPubOfrSchdl";
    url += "&BZ_PROCS_NO=" + scwin.vBzProcsNo;

    await scwin.tx_script_dts_PubOfr();
    const secugrpId = scwin.dts_common_info.getCellData(1, "SECUGRP");
    if (secugrpId === "주식예탁증권" || secugrpId === "외국주권") {
        ipt_med_PARVAL.MaxDecimalPlace = 3;
    } else {
        ipt_med_PARVAL.MaxDecimalPlace = 0;
    }
    /* sdd-asis-lifecycle:end */
};


